 ('goryeo-status-family-society-complete','Goryeo society: aristocracy, work, family and status','Ten original connected essays on Goryeo elite families, local administration, mobility, commoners, nobi, bilateral kinship, women and regional differences.','Ten connected readings',[f'V.3.{i}' for i in range(1,11)]),
 ('korean-empire-gwangmu-modernity-complete','The Korean Empire: sovereignty and modernization','Ten connected readings from the Independence Club through Gojong’s imperial court, the Gwangmu reforms, land, military and infrastructure to diplomacy before 1904.','Ten connected readings',[f'VIII.4.{i}' for i in range(1,11)]),
